fn main() {
    let age = Some(18);

    match age {
        Some(n @ 0..=17) => {
            println!("minor {n}");
        }
        Some(n @ 18..=64) => {
            println!("adult {n}");
        }
        Some(n) => println!("senior {n}"),
        None => println!("unknown"),
    }
}

fn parse(s: &str) -> Option<(&str, u32)> {
    let mut parts = s.split(' ');

    match (parts.next(), parts.next()) {
        (Some(name), Some(n)) => {
            let n = n.parse().ok()?;
            Some((name, n))
        }
        _ => None,
    }
}
